import { useAuth } from "@/_core/hooks/useAuth";
import DashboardLayout, { type NavigationItem } from "@/components/DashboardLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { CalendarDays, CheckCircle2, CircleAlert, ClipboardCheck, Eye, EyeOff, FolderPlus, Layers3, ListTodo, Loader2, Mail, Pencil, Plus, Search, Send, Settings2, ShieldCheck, Trash2, Users, UserRoundPlus, X } from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";

type Event = { id: number; name: string; shortName: string; location: string | null; startDate: string | null; endDate: string | null; status: string };
type Category = { id: number; eventId: number; name: string; color: string };
type Member = { id: number; name: string; email: string | null; role: string; jobTitle: string | null; position: string | null; organization: string | null; phone: string | null; notes: string | null; active: boolean };
type WorkGroup = { id: number; eventId: number; name: string; description: string | null };
type GroupMember = { groupId: number; memberId: number };
type TaskAssignment = { taskId: number; memberId: number | null; groupId: number | null };
type Task = { id: number; eventId: number | null; categoryId: number | null; externalId: string; title: string; description: string | null; status: string; priority: string; dueDate: string | null; progress: number; workBlock: string };
type ConfigurationItem = { id: number; type: "cargo" | "posición" | "categoría" | "otro"; name: string; description: string | null };
type AdminData = { categories: Category[]; groups: WorkGroup[]; members: Member[]; groupMembers: GroupMember[]; taskAssignments: TaskAssignment[]; configuration: ConfigurationItem[] };
type Section = "home" | "tasks" | "people" | "groups" | "categories" | "events" | "settings" | "reviews" | "messages";

const STATUS_OPTIONS = ["Pendiente", "En curso", "Pendiente de verificación", "Resuelta", "Bloqueada"];
const ROLE_OPTIONS = [["collaborator", "Colaborador/a"], ["admin", "Organizador/a administrador/a"]] as const;
const ALL_ROLES = ["admin", "collaborator", "viewer", "user", "direction", "local_member", "scientific", "technical"];

function statusClass(status: string) {
  if (status === "Resuelta") return "bg-emerald-50 text-emerald-700 border-emerald-200";
  if (status === "En curso") return "bg-blue-50 text-blue-700 border-blue-200";
  if (status === "Pendiente de verificación") return "bg-amber-50 text-amber-700 border-amber-200";
  if (status === "Bloqueada") return "bg-rose-50 text-rose-700 border-rose-200";
  return "bg-slate-50 text-slate-600 border-slate-200";
}

function priorityClass(priority: string) {
  return priority === "Alta" ? "bg-rose-50 text-rose-700 border-rose-200" : priority === "Media" ? "bg-amber-50 text-amber-700 border-amber-200" : "bg-slate-50 text-slate-600 border-slate-200";
}

function PageTitle({ kicker, title, description, actions }: { kicker: string; title: string; description: string; actions?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="section-kicker">{kicker}</p><h1 className="mt-2 font-serif text-3xl sm:text-4xl tracking-tight text-[#172334]">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{description}</p></div>{actions && <div className="shrink-0">{actions}</div>}</div>;
}

function Empty({ title, body, icon: Icon = ListTodo }: { title: string; body: string; icon?: typeof ListTodo }) {
  return <div className="rounded-2xl border border-dashed border-slate-300 bg-white px-6 py-12 text-center"><span className="mx-auto grid h-11 w-11 place-items-center rounded-xl bg-slate-100 text-slate-500"><Icon size={20} /></span><h2 className="mt-4 font-semibold text-slate-800">{title}</h2><p className="mx-auto mt-1 max-w-md text-sm leading-6 text-slate-500">{body}</p></div>;
}

function Metric({ label, value, helper, tone, icon: Icon }: { label: string; value: number; helper: string; tone: string; icon: typeof ListTodo }) {
  return <article className="rounded-2xl border border-slate-200 bg-white p-5 shadow-[0_4px_18px_rgba(22,35,52,.035)]"><div className="flex items-start justify-between"><div><p className="text-[11px] font-semibold uppercase tracking-[.09em] text-slate-500">{label}</p><p className="mt-3 text-3xl font-semibold text-[#172334]">{value}</p></div><span className={`grid h-10 w-10 place-items-center rounded-xl ${tone}`}><Icon size={19} /></span></div><p className="mt-3 text-xs text-slate-500">{helper}</p></article>;
}

function TaskTable({ tasks, categories, assignments, members, groups, onOpen, isOrganizer }: { tasks: Task[]; categories: Category[]; assignments: TaskAssignment[]; members: Member[]; groups: WorkGroup[]; onOpen: (task: Task) => void; isOrganizer: boolean }) {
  if (!tasks.length) return <Empty title="No hay tareas para mostrar" body={isOrganizer ? "Crea una tarea y asígnala a una o varias personas o grupos." : "Cuando un organizador te asigne una tarea, aparecerá aquí."} />;
  const assignmentLabel = (taskId: number) => {
    const records = assignments.filter(item => item.taskId === taskId);
    const labels = records.map(item => item.memberId ? members.find(member => member.id === item.memberId)?.name : groups.find(group => group.id === item.groupId)?.name).filter(Boolean);
    return labels.length ? labels.join(" · ") : "Sin asignar";
  };
  return <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-white shadow-[0_4px_18px_rgba(22,35,52,.035)]"><table className="min-w-[790px] w-full text-left"><thead><tr className="border-b border-slate-100 text-[11px] font-semibold uppercase tracking-[.08em] text-slate-500"><th className="px-5 py-3.5">Tarea</th><th className="px-4 py-3.5">Categoría</th>{isOrganizer && <th className="px-4 py-3.5">Asignada a</th>}<th className="px-4 py-3.5">Estado</th><th className="px-4 py-3.5">Avance</th><th className="px-4 py-3.5">Límite</th></tr></thead><tbody className="divide-y divide-slate-100">{tasks.map(task => { const category = categories.find(item => item.id === task.categoryId); return <tr key={task.id} onClick={() => onOpen(task)} className="cursor-pointer hover:bg-[#fbfaf7] transition-colors"><td className="px-5 py-4 max-w-[340px]"><p className="text-sm font-medium leading-5 text-slate-800">{task.title}</p><p className="mt-1 text-[11px] font-medium text-slate-400">{task.externalId}</p></td><td className="px-4 py-4">{category ? <span className="inline-flex items-center gap-1.5 text-xs text-slate-600"><i className="h-2 w-2 rounded-full" style={{ backgroundColor: category.color }} />{category.name}</span> : <span className="text-xs text-slate-400">Sin categoría</span>}</td>{isOrganizer && <td className="px-4 py-4 max-w-[200px] truncate text-xs text-slate-600">{assignmentLabel(task.id)}</td>}<td className="px-4 py-4"><Badge variant="outline" className={statusClass(task.status)}>{task.status}</Badge></td><td className="px-4 py-4"><div className="flex items-center gap-2"><Progress value={task.progress} className="h-1.5 w-14" /><span className="text-xs text-slate-500">{task.progress}%</span></div></td><td className="px-4 py-4 text-xs text-slate-500">{task.dueDate || "—"}</td></tr>; })}</tbody></table></div>;
}

function ToggleRows({ items, selected, onChange, emptyText }: { items: Array<{ id: number; name: string; detail?: string | null }>; selected: number[]; onChange: (ids: number[]) => void; emptyText: string }) {
  if (!items.length) return <p className="rounded-lg bg-slate-50 px-3 py-3 text-xs text-slate-500">{emptyText}</p>;
  return <div className="space-y-1.5 max-h-44 overflow-y-auto pr-1">{items.map(item => { const checked = selected.includes(item.id); return <button type="button" key={item.id} onClick={() => onChange(checked ? selected.filter(id => id !== item.id) : [...selected, item.id])} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left text-sm ${checked ? "bg-[#eaf0f4] text-[#173c59]" : "bg-slate-50 text-slate-600 hover:bg-slate-100"}`}><span className={`grid h-4 w-4 shrink-0 place-items-center rounded border ${checked ? "border-[#173c59] bg-[#173c59] text-white" : "border-slate-300 bg-white"}`}>{checked && "✓"}</span><span className="min-w-0"><span className="block truncate">{item.name}</span>{item.detail && <span className="block truncate text-[11px] text-slate-400">{item.detail}</span>}</span></button>; })}</div>;
}

function TaskDialog({ task, eventId, categories, members, groups, assignments, isOrganizer, onClose }: { task: Task | null; eventId: number; categories: Category[]; members: Member[]; groups: WorkGroup[]; assignments: TaskAssignment[]; isOrganizer: boolean; onClose: () => void }) {
  const utils = trpc.useUtils();
  const [draft, setDraft] = useState<Partial<Task>>({});
  const currentAssignments = task ? assignments.filter(item => item.taskId === task.id) : [];
  const [memberIds, setMemberIds] = useState<number[]>([]);
  const [groupIds, setGroupIds] = useState<number[]>([]);
  const [assignmentMode, setAssignmentMode] = useState(false);
  const [completionNote, setCompletionNote] = useState("");
  const update = trpc.tasks.update.useMutation({ onSuccess: () => { toast.success("Cambios guardados"); utils.tasks.list.invalidate(); utils.workspace.overview.invalidate(); } });
  const assign = trpc.tasks.assign.useMutation({ onSuccess: () => { toast.success("Asignaciones actualizadas"); utils.workspace.adminData.invalidate(); utils.tasks.list.invalidate(); } });
  const submitVerification = trpc.tasks.submitVerification.useMutation({ onSuccess: result => { toast.success(result.noticeSent ? "Tarea enviada a los organizadores para verificación" : "Tarea enviada para verificación"); utils.tasks.list.invalidate(); utils.tasks.verifications.invalidate(); utils.workspace.overview.invalidate(); onClose(); } });
  if (!task) return null;
  const value = <K extends keyof Task>(key: K) => (draft[key] ?? task[key] ?? "") as Task[K];
  const save = () => update.mutate({ id: task.id, data: isOrganizer ? { title: String(value("title")), description: String(value("description")) || null, status: String(value("status")) as "Pendiente" | "En curso" | "Resuelta" | "Bloqueada", priority: String(value("priority")) as "Alta" | "Media" | "Baja", dueDate: String(value("dueDate")) || null, progress: Number(value("progress")), categoryId: Number(value("categoryId")) || null } : { status: String(value("status")) as "Pendiente" | "En curso" | "Resuelta" | "Bloqueada", progress: Number(value("progress")) } });
  const startAssignment = () => { setMemberIds(currentAssignments.filter(item => item.memberId).map(item => item.memberId!)); setGroupIds(currentAssignments.filter(item => item.groupId).map(item => item.groupId!)); setAssignmentMode(true); };
  return <Dialog open={Boolean(task)} onOpenChange={open => !open && onClose()}><DialogContent className="max-w-3xl max-h-[92vh] overflow-y-auto"><DialogHeader><div className="flex gap-2 pr-8"><Badge variant="outline" className={statusClass(task.status)}>{task.status}</Badge><Badge variant="outline" className={priorityClass(task.priority)}>{task.priority}</Badge></div><DialogTitle className="pt-3 font-serif text-2xl leading-tight">{task.title}</DialogTitle><DialogDescription>{isOrganizer ? "Edita la tarea, comprueba propuestas de finalización y asigna cuantas personas o grupos necesites." : "Actualiza el estado y el porcentaje de avance. Cuando termines, solicita al organizador que confirme la finalización."}</DialogDescription></DialogHeader><div className="grid gap-6 py-2 lg:grid-cols-2"><section className="space-y-4"><div><Label>Título</Label><Input disabled={!isOrganizer} className="mt-1.5" value={String(value("title"))} onChange={e => setDraft({ ...draft, title: e.target.value })} /></div><div><Label>Descripción</Label><Textarea disabled={!isOrganizer} className="mt-1.5 min-h-24" value={String(value("description"))} onChange={e => setDraft({ ...draft, description: e.target.value || null })} /></div><div className="grid grid-cols-2 gap-3"><div><Label>Estado</Label>{(!isOrganizer && (task.status === "Resuelta" || task.status === "Pendiente de verificación")) ? <Input className="mt-1.5" disabled value={task.status} /> : <Select value={String(value("status"))} onValueChange={status => setDraft({ ...draft, status })}><SelectTrigger className="mt-1.5"><SelectValue /></SelectTrigger><SelectContent>{STATUS_OPTIONS.filter(status => status === task.status || (status !== "Resuelta" && status !== "Pendiente de verificación")).map(status => <SelectItem key={status} value={status}>{status}</SelectItem>)}</SelectContent></Select>}</div>{isOrganizer && <div><Label>Prioridad</Label><Select value={String(value("priority"))} onValueChange={priority => setDraft({ ...draft, priority })}><SelectTrigger className="mt-1.5"><SelectValue /></SelectTrigger><SelectContent>{["Alta", "Media", "Baja"].map(priority => <SelectItem key={priority} value={priority}>{priority}</SelectItem>)}</SelectContent></Select></div>}</div><div><div className="flex justify-between"><Label>Avance</Label><span className="text-xs font-semibold text-[#9b7333]">{Number(value("progress"))}%</span></div><input type="range" min="0" max="100" step="5" disabled={!isOrganizer && (task.status === "Resuelta" || task.status === "Pendiente de verificación")} className="mt-3 w-full accent-[#a7772f] disabled:opacity-50" value={Number(value("progress"))} onChange={e => setDraft({ ...draft, progress: Number(e.target.value) })} /><Progress value={Number(value("progress"))} className="mt-2 h-2" /></div>{isOrganizer && <div className="grid grid-cols-2 gap-3"><div><Label>Categoría</Label><Select value={String(value("categoryId") || "none")} onValueChange={categoryId => setDraft({ ...draft, categoryId: categoryId === "none" ? null : Number(categoryId) })}><SelectTrigger className="mt-1.5"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Sin categoría</SelectItem>{categories.map(category => <SelectItem key={category.id} value={String(category.id)}>{category.name}</SelectItem>)}</SelectContent></Select></div><div><Label>Fecha límite</Label><Input className="mt-1.5" placeholder="DD/MM/AAAA" value={String(value("dueDate"))} onChange={e => setDraft({ ...draft, dueDate: e.target.value || null })} /></div></div>}<Button onClick={save} disabled={update.isPending || (!isOrganizer && (task.status === "Resuelta" || task.status === "Pendiente de verificación"))} className="w-full bg-[#173c59] hover:bg-[#102f48]">Guardar cambios</Button>{!isOrganizer && task.status !== "Resuelta" && task.status !== "Pendiente de verificación" && <div className="rounded-xl border border-[#dfc48e] bg-[#fff9eb] p-4"><p className="text-sm font-semibold text-[#6b5221]">¿Tarea terminada?</p><p className="mt-1 text-xs leading-5 text-[#80672e]">Envía la tarea a los organizadores para que revisen y confirmen la finalización.</p><Textarea className="mt-3 bg-white" value={completionNote} onChange={event => setCompletionNote(event.target.value)} placeholder="Añade una nota o enlace de entrega (opcional)" /><Button disabled={submitVerification.isPending} onClick={() => submitVerification.mutate({ taskId: task.id, note: completionNote || null })} className="mt-3 w-full bg-[#a7772f] hover:bg-[#8f6423]"><ClipboardCheck className="mr-2" size={16} />Enviar para verificación</Button></div>}</section>
      {isOrganizer && <section className="rounded-xl border border-slate-200 p-4"><div className="flex items-center justify-between"><div><p className="text-sm font-semibold text-slate-800">Asignaciones</p><p className="mt-0.5 text-xs text-slate-500">Una tarea puede asignarse a varias personas y grupos.</p></div><Button variant="outline" size="sm" onClick={startAssignment}>Editar</Button></div><div className="mt-5"><Label>Personas</Label><div className="mt-2"><ToggleRows items={members.filter(member => member.active).map(member => ({ id: member.id, name: member.name, detail: member.email }))} selected={assignmentMode ? memberIds : currentAssignments.filter(item => item.memberId).map(item => item.memberId!)} onChange={ids => { setMemberIds(ids); setAssignmentMode(true); }} emptyText="Añade personas al congreso primero." /></div></div><div className="mt-4"><Label>Grupos</Label><div className="mt-2"><ToggleRows items={groups.map(group => ({ id: group.id, name: group.name, detail: group.description }))} selected={assignmentMode ? groupIds : currentAssignments.filter(item => item.groupId).map(item => item.groupId!)} onChange={ids => { setGroupIds(ids); setAssignmentMode(true); }} emptyText="Crea un grupo para asignarlo aquí." /></div></div><Button className="mt-4 w-full bg-[#a7772f] hover:bg-[#8f6423]" onClick={() => assign.mutate({ taskId: task.id, memberIds: assignmentMode ? memberIds : currentAssignments.filter(item => item.memberId).map(item => item.memberId!), groupIds: assignmentMode ? groupIds : currentAssignments.filter(item => item.groupId).map(item => item.groupId!) })} disabled={assign.isPending}>Aplicar asignaciones</Button></section>}</div></DialogContent></Dialog>;
}

function NewTask({ open, eventId, categories, onClose }: { open: boolean; eventId: number; categories: Category[]; onClose: () => void }) {
  const utils = trpc.useUtils(); const [form, setForm] = useState({ title: "", description: "", priority: "Media", dueDate: "", categoryId: "none" }); const create = trpc.tasks.create.useMutation({ onSuccess: () => { utils.tasks.list.invalidate(); utils.workspace.overview.invalidate(); utils.workspace.adminData.invalidate(); toast.success("Tarea creada; ya puedes asignarla."); onClose(); } });
  return <Dialog open={open} onOpenChange={openNow => !openNow && onClose()}><DialogContent><DialogHeader><DialogTitle>Nueva tarea</DialogTitle><DialogDescription>Crea la tarea primero. Después podrás asignarla a una o varias personas y grupos.</DialogDescription></DialogHeader><div className="space-y-4"><div><Label>Tarea</Label><Input className="mt-1.5" autoFocus value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Ej.: Confirmar la reserva de salas" /></div><div><Label>Descripción</Label><Textarea className="mt-1.5" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></div><div className="grid grid-cols-2 gap-3"><div><Label>Categoría</Label><Select value={form.categoryId} onValueChange={categoryId => setForm({ ...form, categoryId })}><SelectTrigger className="mt-1.5"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Sin categoría</SelectItem>{categories.map(category => <SelectItem key={category.id} value={String(category.id)}>{category.name}</SelectItem>)}</SelectContent></Select></div><div><Label>Prioridad</Label><Select value={form.priority} onValueChange={priority => setForm({ ...form, priority })}><SelectTrigger className="mt-1.5"><SelectValue /></SelectTrigger><SelectContent>{["Alta", "Media", "Baja"].map(priority => <SelectItem key={priority} value={priority}>{priority}</SelectItem>)}</SelectContent></Select></div></div><div><Label>Fecha límite</Label><Input className="mt-1.5" placeholder="DD/MM/AAAA" value={form.dueDate} onChange={e => setForm({ ...form, dueDate: e.target.value })} /></div><Button disabled={!form.title || create.isPending} onClick={() => create.mutate({ eventId, title: form.title, description: form.description || null, priority: form.priority as "Alta" | "Media" | "Baja", dueDate: form.dueDate || null, categoryId: form.categoryId === "none" ? null : Number(form.categoryId) })} className="w-full bg-[#173c59] hover:bg-[#102f48]">Crear tarea</Button></div></DialogContent></Dialog>;
}

function TaskListView({ title, subtitle, tasks, categories, data, isOrganizer, onOpen, onCreate }: { title: string; subtitle: string; tasks: Task[]; categories: Category[]; data: AdminData; isOrganizer: boolean; onOpen: (task: Task) => void; onCreate: () => void }) {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState("Todas"); const [showResolved, setShowResolved] = useState(false);
  const filtered = useMemo(() => tasks.filter(task => (showResolved || status === "Resuelta" || task.status !== "Resuelta") && (!search || `${task.title} ${task.externalId} ${task.workBlock}`.toLowerCase().includes(search.toLowerCase())) && (status === "Todas" || task.status === status)), [tasks, search, status, showResolved]);
  const resolvedCount = tasks.filter(task => task.status === "Resuelta").length;
  return <><PageTitle kicker={isOrganizer ? "Gestión del congreso" : "Tu espacio de trabajo"} title={title} description={subtitle} actions={isOrganizer ? <Button onClick={onCreate} className="bg-[#173c59] hover:bg-[#102f48]"><Plus className="mr-2" size={16} />Nueva tarea</Button> : undefined} /><div className="mb-5 grid gap-3 rounded-2xl border border-slate-200 bg-white p-3 sm:grid-cols-[1fr_190px]"><div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={17} /><Input className="border-0 bg-slate-50 pl-9" placeholder="Buscar tarea…" value={search} onChange={e => setSearch(e.target.value)} /></div><Select value={status} onValueChange={setStatus}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="Todas">Todos los estados</SelectItem>{STATUS_OPTIONS.map(item => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select><Button variant="outline" className="sm:col-span-2 justify-center" onClick={() => setShowResolved(!showResolved)}>{showResolved ? <EyeOff className="mr-2" size={16} /> : <Eye className="mr-2" size={16} />}{showResolved ? "Ocultar" : "Ver"} tareas resueltas ({resolvedCount})</Button></div><p className="mb-3 text-xs text-slate-500"><strong className="text-slate-700">{filtered.length}</strong> tareas mostradas{!showResolved && status !== "Resuelta" && resolvedCount ? ` · ${resolvedCount} resueltas ocultas` : ""}</p><TaskTable tasks={filtered} categories={categories} assignments={data.taskAssignments} members={data.members} groups={data.groups} onOpen={onOpen} isOrganizer={isOrganizer} /></>;
}

function HomeView({ event, summary, loading, onTasks, isOrganizer }: { event?: Event; summary?: { total: number; pending: number; active: number; done: number; assigned: Task[] }; loading: boolean; onTasks: () => void; isOrganizer: boolean }) {
  if (loading || !summary) return <div className="h-64 grid place-items-center"><Loader2 className="animate-spin text-[#a7772f]" /></div>;
  return <><PageTitle kicker={event?.shortName ?? "Congreso"} title={event?.name ?? "Mis tareas"} description={event ? `${event.location ?? "Ubicación por definir"} · ${event.startDate ?? "Fechas por definir"}${event.endDate ? ` – ${event.endDate}` : ""}` : "Selecciona un congreso para empezar."} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label={isOrganizer ? "Todas las tareas" : "Mis tareas"} value={summary.total} helper={isOrganizer ? "Tareas activas en el congreso" : "Tareas asignadas a ti o a tus grupos"} tone="bg-[#e8eef4] text-[#275170]" icon={ListTodo} /><Metric label="Pendientes" value={summary.pending} helper="Esperando inicio" tone="bg-slate-100 text-slate-600" icon={CircleAlert} /><Metric label="En curso" value={summary.active} helper="Con trabajo activo" tone="bg-blue-50 text-blue-700" icon={CalendarDays} /><Metric label="Resueltas" value={summary.done} helper="Trabajo finalizado" tone="bg-emerald-50 text-emerald-700" icon={CheckCircle2} /></div><section className="mt-7 rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="section-kicker">Prioridad de hoy</p><h2 className="mt-1 text-lg font-semibold text-slate-800">{isOrganizer ? "Próximas tareas del congreso" : "Tus próximas tareas"}</h2></div><Button variant="outline" onClick={onTasks}>Ver todas</Button></div>{summary.assigned.length ? <div className="mt-4 divide-y divide-slate-100">{summary.assigned.map(task => <button onClick={onTasks} key={task.id} className="flex w-full items-center gap-3 py-3 text-left"><span className="flex-1 text-sm font-medium text-slate-700">{task.title}</span><Badge variant="outline" className={statusClass(task.status)}>{task.status}</Badge></button>)}</div> : <p className="mt-5 text-sm text-slate-500">Aún no tienes tareas asignadas para este congreso.</p>}</section></>;
}

function PeopleView({ data }: { data: AdminData }) {
  const utils = trpc.useUtils();
  const blank = { name: "", email: "", password: "", role: "collaborator", jobTitle: "", position: "", organization: "", phone: "", notes: "" };
  const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Member | null>(null); const [form, setForm] = useState(blank);
  const create = trpc.members.create.useMutation({ onSuccess: () => { utils.workspace.adminData.invalidate(); toast.success("Cuenta creada correctamente"); setOpen(false); } });
  const update = trpc.members.update.useMutation({ onSuccess: () => { utils.workspace.adminData.invalidate(); toast.success("Perfil actualizado"); setEditing(null); } });
  const jobs = data.configuration.filter(item => item.type === "cargo"); const positions = data.configuration.filter(item => item.type === "posición");
  const openCreate = () => { setForm(blank); setEditing(null); setOpen(true); };
  const openEdit = (member: Member) => { setEditing(member); setForm({ name: member.name, email: member.email ?? "", password: "", role: member.role === "admin" || member.role === "direction" ? "admin" : "collaborator", jobTitle: member.jobTitle ?? "", position: member.position ?? "", organization: member.organization ?? "", phone: member.phone ?? "", notes: member.notes ?? "" }); setOpen(true); };
  const save = () => {
    const details = { name: form.name, email: form.email, role: form.role as "admin" | "collaborator", jobTitle: form.jobTitle || null, position: form.position || null, organization: form.organization || null, phone: form.phone || null, notes: form.notes || null };
    if (editing) update.mutate({ id: editing.id, ...details, ...(form.password ? { password: form.password } : {}) });
    else create.mutate({ ...details, password: form.password });
  };
  return <><PageTitle kicker="Organización" title="Personas y cuentas" description="Crea una cuenta con correo y clave. Añade datos de contacto, cargo, posición y notas; después asigna tareas o grupos." actions={<Button onClick={openCreate} className="bg-[#173c59] hover:bg-[#102f48]"><UserRoundPlus className="mr-2" size={16} />Crear usuario</Button>} />
    <div className="mb-5 rounded-xl border border-[#dfc48e] bg-[#fff9eb] px-4 py-3 text-sm text-[#6b5221]"><ShieldCheck className="mr-2 inline" size={17} /><strong>Acceso simple:</strong> un organizador administrador controla todo. Cada colaborador inicia sesión con su correo y clave, y sólo ve las tareas asignadas directamente o mediante sus grupos.</div>
    <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-white"><table className="min-w-[850px] w-full text-left"><thead><tr className="border-b border-slate-100 text-[11px] uppercase tracking-[.08em] text-slate-500"><th className="px-5 py-3">Persona y acceso</th><th className="px-4 py-3">Cargo / posición</th><th className="px-4 py-3">Organización</th><th className="px-4 py-3">Perfil</th><th className="px-4 py-3">Estado</th><th className="px-4 py-3"></th></tr></thead><tbody className="divide-y divide-slate-100">{data.members.map(member => <tr key={member.id}><td className="px-5 py-4"><p className="text-sm font-medium text-slate-800">{member.name}</p><p className="mt-1 text-xs text-slate-500">{member.email || "Sin cuenta local"}</p></td><td className="px-4 py-4 text-sm text-slate-600">{member.jobTitle || "—"}<span className="text-slate-400">{member.position ? ` · ${member.position}` : ""}</span></td><td className="px-4 py-4 text-sm text-slate-600">{member.organization || "—"}</td><td className="px-4 py-4"><Badge variant="outline" className={member.role === "admin" || member.role === "direction" ? "bg-[#e8eef4] text-[#275170] border-[#c8d6e2]" : "bg-slate-50 text-slate-600"}>{member.role === "admin" || member.role === "direction" ? "Administrador" : "Colaborador/a"}</Badge></td><td className="px-4 py-4"><button onClick={() => update.mutate({ id: member.id, active: !member.active })}><Badge variant="outline" className={member.active ? "bg-emerald-50 text-emerald-700 border-emerald-200" : "bg-slate-50 text-slate-500"}>{member.active ? "Activo" : "Suspendido"}</Badge></button></td><td className="px-4 py-4"><Button variant="outline" size="sm" onClick={() => openEdit(member)}><Pencil size={14} className="mr-1.5" />Editar</Button></td></tr>)}</tbody></table></div>
    <Dialog open={open} onOpenChange={value => { if (!value) { setOpen(false); setEditing(null); } }}><DialogContent className="max-w-2xl max-h-[92vh] overflow-y-auto"><DialogHeader><DialogTitle>{editing ? "Editar persona" : "Crear usuario"}</DialogTitle><DialogDescription>{editing ? "Actualiza los datos, permisos o la clave. Deja la nueva clave vacía si no quieres cambiarla." : "Esta persona podrá acceder con el correo y la clave que definas."}</DialogDescription></DialogHeader><div className="grid gap-4 py-2 sm:grid-cols-2"><div><Label>Nombre completo</Label><Input className="mt-1.5" value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></div><div><Label>Correo de acceso</Label><Input className="mt-1.5" type="email" value={form.email} onChange={event => setForm({ ...form, email: event.target.value })} /></div><div className="sm:col-span-2"><Label>{editing ? "Nueva clave (opcional)" : "Clave de acceso"}</Label><Input className="mt-1.5" type="password" autoComplete="new-password" value={form.password} onChange={event => setForm({ ...form, password: event.target.value })} placeholder="Mínimo 10 caracteres, letras y números" /></div><div><Label>Perfil</Label><Select value={form.role} onValueChange={role => setForm({ ...form, role })}><SelectTrigger className="mt-1.5"><SelectValue /></SelectTrigger><SelectContent>{ROLE_OPTIONS.map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div><div><Label>Cargo</Label><Input className="mt-1.5" list="cargo-options" value={form.jobTitle} onChange={event => setForm({ ...form, jobTitle: event.target.value })} placeholder="Ej.: Chair" /><datalist id="cargo-options">{jobs.map(item => <option key={item.id} value={item.name} />)}</datalist></div><div><Label>Posición</Label><Input className="mt-1.5" list="position-options" value={form.position} onChange={event => setForm({ ...form, position: event.target.value })} placeholder="Ej.: Responsable" /><datalist id="position-options">{positions.map(item => <option key={item.id} value={item.name} />)}</datalist></div><div><Label>Organización</Label><Input className="mt-1.5" value={form.organization} onChange={event => setForm({ ...form, organization: event.target.value })} /></div><div><Label>Teléfono</Label><Input className="mt-1.5" value={form.phone} onChange={event => setForm({ ...form, phone: event.target.value })} /></div><div className="sm:col-span-2"><Label>Notas internas</Label><Textarea className="mt-1.5" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><Button disabled={!form.name || !form.email || (!editing && !form.password)} onClick={save} className="sm:col-span-2 bg-[#173c59] hover:bg-[#102f48]">{editing ? "Guardar cambios" : "Crear cuenta"}</Button></div></DialogContent></Dialog></>;
}

function GroupsView({ data, eventId }: { data: AdminData; eventId: number }) {
  const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<WorkGroup | null>(null); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [selected, setSelected] = useState<number[]>([]); const create = trpc.groups.create.useMutation({ onSuccess: () => { utils.workspace.adminData.invalidate(); toast.success("Grupo creado"); setOpen(false); } }); const setMembers = trpc.groups.setMembers.useMutation({ onSuccess: () => { utils.workspace.adminData.invalidate(); toast.success("Miembros del grupo actualizados"); setEditing(null); } });
  const edit = (group: WorkGroup) => { setEditing(group); setSelected(data.groupMembers.filter(row => row.groupId === group.id).map(row => row.memberId)); };
  return <><PageTitle kicker="Asignación en equipo" title="Grupos" description="Crea grupos de trabajo y añade tantas personas como necesites. Toda tarea asignada a un grupo será visible para sus miembros." actions={<Button onClick={() => setOpen(true)} className="bg-[#173c59] hover:bg-[#102f48]"><FolderPlus className="mr-2" size={16} />Crear grupo</Button>} /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.groups.map(group => { const memberNames = data.groupMembers.filter(row => row.groupId === group.id).map(row => data.members.find(member => member.id === row.memberId)?.name).filter(Boolean); return <article key={group.id} className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-serif text-xl text-[#172334]">{group.name}</h2><p className="mt-1 text-xs leading-5 text-slate-500">{group.description || "Sin descripción"}</p></div><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#e8eef4] text-[#275170]"><Users size={18} /></span></div><p className="mt-5 text-xs font-semibold uppercase tracking-[.08em] text-slate-400">{memberNames.length} miembros</p><p className="mt-2 min-h-10 text-sm leading-5 text-slate-600">{memberNames.length ? memberNames.join(" · ") : "Todavía no hay personas en el grupo."}</p><Button variant="outline" className="mt-5 w-full" onClick={() => edit(group)}>Gestionar personas</Button></article>; })}</div><Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Crear grupo</DialogTitle><DialogDescription>Ejemplos: Logística, Comunicación, Programa o Patrocinio.</DialogDescription></DialogHeader><div className="space-y-4"><div><Label>Nombre del grupo</Label><Input className="mt-1.5" value={name} onChange={e => setName(e.target.value)} /></div><div><Label>Descripción</Label><Textarea className="mt-1.5" value={description} onChange={e => setDescription(e.target.value)} /></div><Button disabled={!name} className="w-full bg-[#173c59] hover:bg-[#102f48]" onClick={() => create.mutate({ eventId, name, description: description || null })}>Crear grupo</Button></div></DialogContent></Dialog><Dialog open={Boolean(editing)} onOpenChange={openNow => !openNow && setEditing(null)}><DialogContent><DialogHeader><DialogTitle>Personas de {editing?.name}</DialogTitle><DialogDescription>Selecciona todas las personas que deben recibir las tareas asignadas a este grupo.</DialogDescription></DialogHeader><ToggleRows items={data.members.filter(member => member.active).map(member => ({ id: member.id, name: member.name, detail: member.email }))} selected={selected} onChange={setSelected} emptyText="No hay personas activas." /><Button className="mt-2 w-full bg-[#173c59] hover:bg-[#102f48]" onClick={() => editing && setMembers.mutate({ groupId: editing.id, memberIds: selected })}>Guardar miembros</Button></DialogContent></Dialog></>;
}

function CategoriesView({ categories, eventId }: { categories: Category[]; eventId: number }) {
  const utils = trpc.useUtils(); const [name, setName] = useState(""); const [color, setColor] = useState("#173c59"); const [editing, setEditing] = useState<Category | null>(null);
  const create = trpc.categories.create.useMutation({ onSuccess: () => { utils.workspace.adminData.invalidate(); toast.success("Categoría creada"); setName(""); } }); const update = trpc.categories.update.useMutation({ onSuccess: () => { utils.workspace.adminData.invalidate(); toast.success("Categoría actualizada"); setEditing(null); } }); const remove = trpc.categories.remove.useMutation({ onSuccess: result => { utils.workspace.adminData.invalidate(); utils.tasks.list.invalidate(); toast.success(result.affectedTasks ? `Categoría eliminada; ${result.affectedTasks} tareas quedan sin categoría.` : "Categoría eliminada"); } });
  return <><PageTitle kicker="Organización de tareas" title="Categorías" description="Las categorías pertenecen al congreso activo. Puedes crearlas, modificarlas o eliminarlas sin borrar las tareas asociadas." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><section className="rounded-2xl border border-slate-200 bg-white p-5 h-fit"><h2 className="font-semibold text-slate-800">Nueva categoría</h2><div className="mt-4 space-y-4"><div><Label>Nombre</Label><Input className="mt-1.5" value={name} onChange={e => setName(e.target.value)} placeholder="Ej.: Logística" /></div><div><Label>Color</Label><div className="mt-1.5 flex gap-2"><input aria-label="Color de categoría" className="h-10 w-12 rounded border border-slate-200 p-1" type="color" value={color} onChange={e => setColor(e.target.value)} /><Input value={color} onChange={e => setColor(e.target.value)} /></div></div><Button disabled={!name || !/^#[0-9a-fA-F]{6}$/.test(color)} className="w-full bg-[#173c59] hover:bg-[#102f48]" onClick={() => create.mutate({ eventId, name, color })}>Crear categoría</Button></div></section><section className="grid gap-3 sm:grid-cols-2">{categories.map(category => <article key={category.id} className="rounded-xl border border-slate-200 bg-white px-4 py-4 flex items-center gap-3"><i className="h-9 w-2 rounded-full" style={{ backgroundColor: category.color }} /><div className="min-w-0 flex-1"><h2 className="font-medium text-slate-800 truncate">{category.name}</h2><p className="mt-1 font-mono text-[11px] text-slate-500">{category.color}</p></div><div className="flex gap-1"><Button variant="outline" size="sm" onClick={() => setEditing(category)}><Pencil size={13} /></Button><Button variant="outline" size="sm" className="text-rose-600 hover:text-rose-700" onClick={() => { if (window.confirm(`¿Eliminar la categoría “${category.name}”? Las tareas se conservarán sin categoría.`)) remove.mutate({ id: category.id }); }}><Trash2 size={13} /></Button></div></article>)}{!categories.length && <Empty title="Sin categorías" body="Crea la primera categoría para el congreso." icon={Layers3} />}</section></div><Dialog open={Boolean(editing)} onOpenChange={open => !open && setEditing(null)}><DialogContent><DialogHeader><DialogTitle>Editar categoría</DialogTitle><DialogDescription>Este cambio se aplica a las tareas vinculadas a la categoría.</DialogDescription></DialogHeader><div className="space-y-4"><div><Label>Nombre</Label><Input className="mt-1.5" value={editing?.name ?? ""} onChange={event => setEditing(current => current ? { ...current, name: event.target.value } : current)} /></div><div><Label>Color</Label><div className="mt-1.5 flex gap-2"><input aria-label="Color de categoría" className="h-10 w-12 rounded border border-slate-200 p-1" type="color" value={editing?.color ?? "#173c59"} onChange={event => setEditing(current => current ? { ...current, color: event.target.value } : current)} /><Input value={editing?.color ?? ""} onChange={event => setEditing(current => current ? { ...current, color: event.target.value } : current)} /></div></div><Button disabled={!editing?.name || !/^#[0-9a-fA-F]{6}$/.test(editing?.color ?? "")} onClick={() => editing && update.mutate({ id: editing.id, name: editing.name, color: editing.color })} className="w-full bg-[#173c59] hover:bg-[#102f48]">Guardar categoría</Button></div></DialogContent></Dialog></>;
}

function SettingsView({ data, onCategories }: { data: AdminData; onCategories: () => void }) {
  const utils = trpc.useUtils();
  const [open, setOpen] = useState(false); const [editing, setEditing] = useState<ConfigurationItem | null>(null);
  const [form, setForm] = useState({ type: "cargo" as "cargo" | "posición" | "categoría" | "otro", name: "", description: "" });
  const create = trpc.configuration.create.useMutation({ onSuccess: () => { utils.workspace.adminData.invalidate(); toast.success("Opción añadida"); setOpen(false); } });
  const update = trpc.configuration.update.useMutation({ onSuccess: () => { utils.workspace.adminData.invalidate(); toast.success("Opción actualizada"); setEditing(null); setOpen(false); } });
  const openNew = () => { setEditing(null); setForm({ type: "cargo", name: "", description: "" }); setOpen(true); };
  const openEdit = (item: ConfigurationItem) => { setEditing(item); setForm({ type: item.type, name: item.name, description: item.description ?? "" }); setOpen(true); };
  const sections: Array<["cargo" | "posición" | "categoría" | "otro", string, string]> = [["cargo", "Cargos", "Ej.: Chair, Co-Chair o Secretaría técnica."], ["posición", "Posiciones", "Ej.: Responsable, Miembro o Apoyo."], ["otro", "Otras opciones", "Información común que quieras mantener como catálogo."]];
  return <><PageTitle kicker="Administración del sistema" title="Configuración" description="Gestiona los valores reutilizables de personas y la organización de cada congreso." actions={<Button onClick={openNew} className="bg-[#173c59] hover:bg-[#102f48]"><Plus className="mr-2" size={16} />Añadir opción</Button>} />
    <div className="grid gap-5 xl:grid-cols-[1fr_.75fr]"> <section className="space-y-5">{sections.map(([type, title, description]) => { const items = data.configuration.filter(item => item.type === type); return <article key={type} className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-semibold text-slate-800">{title}</h2><p className="mt-1 text-xs leading-5 text-slate-500">{description}</p></div><Badge variant="outline" className="bg-slate-50 text-slate-500">{items.length}</Badge></div><div className="mt-4 divide-y divide-slate-100">{items.length ? items.map(item => <div key={item.id} className="flex items-center gap-3 py-3"><div className="min-w-0 flex-1"><p className="text-sm font-medium text-slate-700">{item.name}</p>{item.description && <p className="mt-0.5 text-xs text-slate-500">{item.description}</p>}</div><Button variant="outline" size="sm" onClick={() => openEdit(item)}><Pencil size={13} className="mr-1.5" />Editar</Button></div>) : <p className="py-3 text-sm text-slate-500">No hay opciones creadas.</p>}</div></article>; })}</section>
      <aside className="rounded-2xl bg-[#173c59] p-6 text-white h-fit"><Settings2 size={22} className="text-[#e4c17d]" /><h2 className="mt-4 font-serif text-2xl">Categorías del congreso</h2><p className="mt-3 text-sm leading-6 text-slate-300">Las categorías pertenecen a cada congreso, porque las necesidades de un evento no tienen por qué repetirse en el siguiente.</p><Button onClick={onCategories} className="mt-5 bg-[#d1a757] text-[#102d45] hover:bg-[#c49a4c]">Gestionar categorías</Button></aside></div>
    <Dialog open={open} onOpenChange={value => !value && setOpen(false)}><DialogContent><DialogHeader><DialogTitle>{editing ? "Editar opción" : "Añadir opción"}</DialogTitle><DialogDescription>Las opciones se muestran como sugerencias al editar las personas.</DialogDescription></DialogHeader><div className="space-y-4"><div><Label>Tipo</Label><Select value={form.type} onValueChange={type => setForm({ ...form, type: type as "cargo" | "posición" | "categoría" | "otro" })}><SelectTrigger className="mt-1.5"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="cargo">Cargo</SelectItem><SelectItem value="posición">Posición</SelectItem><SelectItem value="otro">Otra opción</SelectItem></SelectContent></Select></div><div><Label>Nombre</Label><Input className="mt-1.5" value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></div><div><Label>Descripción</Label><Textarea className="mt-1.5" value={form.description} onChange={event => setForm({ ...form, description: event.target.value })} /></div><Button disabled={!form.name} onClick={() => editing ? update.mutate({ id: editing.id, ...form, description: form.description || null }) : create.mutate({ ...form, description: form.description || null })} className="w-full bg-[#173c59] hover:bg-[#102f48]">{editing ? "Guardar opción" : "Añadir opción"}</Button></div></DialogContent></Dialog></>;
}

function ReviewsView({ eventId }: { eventId: number }) {
  const utils = trpc.useUtils();
  const reviews = trpc.tasks.pendingReviews.useQuery({ eventId });
  const [notes, setNotes] = useState<Record<number, string>>({});
  const action = trpc.tasks.reviewVerification.useMutation({ onSuccess: result => { toast.success(result.noticeSent ? "Revisión registrada y correo enviado" : "Revisión registrada"); utils.tasks.pendingReviews.invalidate(); utils.tasks.list.invalidate(); utils.workspace.overview.invalidate(); } });
  const items = reviews.data ?? [];
  return <><PageTitle kicker="Control de calidad" title="Verificaciones pendientes" description="Cuando una persona marca una tarea como terminada, aparecerá aquí. Confírmala para marcarla como resuelta o devuélvela con un comentario." />
    {!items.length && !reviews.isLoading ? <Empty title="No hay tareas pendientes de verificación" body="Las tareas que los colaboradores terminen y envíen para revisión aparecerán aquí." icon={ClipboardCheck} /> : <div className="space-y-4">{items.map(review => <article key={review.id} className="rounded-2xl border border-[#e1cfab] bg-white p-5 shadow-[0_4px_18px_rgba(22,35,52,.035)]"><div className="flex flex-col justify-between gap-4 sm:flex-row"><div><Badge variant="outline" className="bg-amber-50 text-amber-700 border-amber-200">Pendiente de verificación</Badge><h2 className="mt-3 text-lg font-semibold text-slate-800">{review.task?.title || "Tarea eliminada"}</h2><p className="mt-1 text-sm text-slate-500">Enviada por <strong>{review.submittedByName}</strong> · {new Date(review.submittedAt).toLocaleString("es-ES")}</p></div><ClipboardCheck className="shrink-0 text-[#a7772f]" size={24} /></div><div className="mt-4 rounded-xl bg-[#fff9eb] p-4 text-sm leading-6 text-[#695524]"><strong>Nota del colaborador:</strong><br />{review.note || "Sin nota adicional."}</div><div className="mt-4"><Label>Comentario para la persona (opcional)</Label><Textarea className="mt-1.5" value={notes[review.id] ?? ""} onChange={event => setNotes({ ...notes, [review.id]: event.target.value })} placeholder="Indica qué se ha comprobado o qué debe completarse." /></div><div className="mt-4 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Button variant="outline" className="text-rose-700 hover:text-rose-800" disabled={action.isPending} onClick={() => action.mutate({ verificationId: review.id, decision: "return", note: notes[review.id] || null })}>Devolver para completar</Button><Button className="bg-emerald-700 hover:bg-emerald-800" disabled={action.isPending} onClick={() => action.mutate({ verificationId: review.id, decision: "confirm", note: notes[review.id] || null })}><CheckCircle2 className="mr-2" size={16} />Confirmar como resuelta</Button></div></article>)}</div>}</>;
}

function MessagingView({ eventId, data }: { eventId: number; data: AdminData }) {
  const utils = trpc.useUtils();
  const smtpQuery = trpc.messaging.smtp.useQuery();
  const historyQuery = trpc.messaging.history.useQuery({ eventId });
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [members, setMembers] = useState<number[]>([]); const [groups, setGroups] = useState<number[]>([]);
  const [message, setMessage] = useState({ subject: "", body: "" });
  const [smtp, setSmtp] = useState({ host: "", port: "587", username: "", password: "", fromName: "Gestor de congresos", fromEmail: "", secure: false });
  const saveSmtp = trpc.messaging.saveSmtp.useMutation({ onSuccess: () => { utils.messaging.smtp.invalidate(); toast.success("Configuración SMTP guardada"); setSettingsOpen(false); } });
  const send = trpc.messaging.send.useMutation({ onSuccess: result => { utils.messaging.history.invalidate(); toast.success(`Correo enviado a ${result.recipientCount} destinatarios`); setMessage({ subject: "", body: "" }); setMembers([]); setGroups([]); } });
  const openSettings = () => { const current = smtpQuery.data; setSmtp({ host: current?.host ?? "", port: String(current?.port ?? 587), username: current?.username ?? "", password: "", fromName: current?.fromName ?? "Gestor de congresos", fromEmail: current?.fromEmail ?? "", secure: current?.secure ?? false }); setSettingsOpen(true); };
  const hasSmtp = Boolean(smtpQuery.data);
  return <><PageTitle kicker="Comunicación" title="Enviar correo" description="Escribe un mensaje y selecciónalo para una o varias personas o grupos. Los grupos se resuelven automáticamente en sus miembros activos con correo." actions={<Button variant="outline" onClick={openSettings}><Settings2 className="mr-2" size={16} />Configurar SMTP</Button>} />
    {!hasSmtp && <div className="mb-5 rounded-xl border border-[#dfc48e] bg-[#fff9eb] p-4 text-sm text-[#6b5221]"><Mail className="mr-2 inline" size={17} /><strong>SMTP pendiente.</strong> Configura el servidor de correo antes de enviar mensajes. Las credenciales se guardan cifradas.</div>}
    <div className="grid gap-5 xl:grid-cols-[.78fr_1.22fr]"><section className="rounded-2xl border border-slate-200 bg-white p-5 h-fit"><h2 className="font-semibold text-slate-800">Destinatarios</h2><p className="mt-1 text-xs leading-5 text-slate-500">Puedes combinar personas y grupos. Los correos duplicados se eliminan al enviar.</p><div className="mt-5"><Label>Personas</Label><div className="mt-2"><ToggleRows items={data.members.filter(member => member.active && member.email).map(member => ({ id: member.id, name: member.name, detail: member.email }))} selected={members} onChange={setMembers} emptyText="No hay personas con correo activo." /></div></div><div className="mt-5"><Label>Grupos</Label><div className="mt-2"><ToggleRows items={data.groups.map(group => ({ id: group.id, name: group.name, detail: group.description }))} selected={groups} onChange={setGroups} emptyText="No hay grupos creados." /></div></div></section>
      <section className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="font-semibold text-slate-800">Mensaje</h2><div className="mt-4"><Label>Asunto</Label><Input className="mt-1.5" value={message.subject} onChange={event => setMessage({ ...message, subject: event.target.value })} placeholder="Ej.: Reunión de coordinación" /></div><div className="mt-4"><Label>Texto del correo</Label><Textarea className="mt-1.5 min-h-48" value={message.body} onChange={event => setMessage({ ...message, body: event.target.value })} placeholder="Escribe el mensaje que recibirán las personas seleccionadas." /></div><Button disabled={!hasSmtp || !message.subject || !message.body || (!members.length && !groups.length) || send.isPending} onClick={() => send.mutate({ eventId, memberIds: members, groupIds: groups, subject: message.subject, body: message.body })} className="mt-5 w-full bg-[#173c59] hover:bg-[#102f48]"><Send className="mr-2" size={16} />Enviar correo</Button></section></div>
    <section className="mt-7"><p className="section-kicker">Trazabilidad</p><h2 className="mt-1 text-lg font-semibold text-slate-800">Últimos envíos</h2><div className="mt-3 overflow-x-auto rounded-2xl border border-slate-200 bg-white"><table className="min-w-[680px] w-full text-left"><thead><tr className="border-b border-slate-100 text-[11px] uppercase tracking-[.08em] text-slate-500"><th className="px-5 py-3">Asunto</th><th className="px-4 py-3">Destinatarios</th><th className="px-4 py-3">Enviado por</th><th className="px-4 py-3">Estado</th></tr></thead><tbody className="divide-y divide-slate-100">{(historyQuery.data ?? []).slice().reverse().slice(0, 10).map(item => <tr key={item.id}><td className="px-5 py-3"><p className="text-sm font-medium text-slate-700">{item.subject}</p><p className="mt-0.5 text-xs text-slate-400">{new Date(item.createdAt).toLocaleString("es-ES")}</p></td><td className="px-4 py-3 text-sm text-slate-600">{item.recipientCount}</td><td className="px-4 py-3 text-sm text-slate-600">{item.createdBy}</td><td className="px-4 py-3"><Badge variant="outline" className={item.status === "Enviado" ? "bg-emerald-50 text-emerald-700 border-emerald-200" : "bg-rose-50 text-rose-700 border-rose-200"}>{item.status}</Badge></td></tr>)}{!(historyQuery.data ?? []).length && <tr><td colSpan={4} className="px-5 py-7 text-center text-sm text-slate-500">Todavía no hay correos enviados desde esta aplicación.</td></tr>}</tbody></table></div></section>
    <Dialog open={settingsOpen} onOpenChange={setSettingsOpen}><DialogContent className="max-w-xl"><DialogHeader><DialogTitle>Configuración SMTP</DialogTitle><DialogDescription>Introduce los datos del proveedor de correo. La contraseña no se muestra de nuevo y queda cifrada en la base de datos.</DialogDescription></DialogHeader><div className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Label>Servidor SMTP</Label><Input className="mt-1.5" value={smtp.host} onChange={event => setSmtp({ ...smtp, host: event.target.value })} placeholder="smtp.su-dominio.es" /></div><div><Label>Puerto</Label><Input className="mt-1.5" type="number" value={smtp.port} onChange={event => setSmtp({ ...smtp, port: event.target.value })} /></div><div className="flex items-end pb-2"><label className="flex cursor-pointer items-center gap-2 text-sm text-slate-600"><input type="checkbox" checked={smtp.secure} onChange={event => setSmtp({ ...smtp, secure: event.target.checked })} />Usar TLS directo</label></div><div><Label>Usuario SMTP</Label><Input className="mt-1.5" value={smtp.username} onChange={event => setSmtp({ ...smtp, username: event.target.value })} /></div><div><Label>{smtpQuery.data?.hasPassword ? "Nueva contraseña (opcional)" : "Contraseña SMTP"}</Label><Input className="mt-1.5" type="password" autoComplete="new-password" value={smtp.password} onChange={event => setSmtp({ ...smtp, password: event.target.value })} /></div><div><Label>Nombre remitente</Label><Input className="mt-1.5" value={smtp.fromName} onChange={event => setSmtp({ ...smtp, fromName: event.target.value })} /></div><div><Label>Correo remitente</Label><Input className="mt-1.5" type="email" value={smtp.fromEmail} onChange={event => setSmtp({ ...smtp, fromEmail: event.target.value })} /></div><Button disabled={!smtp.host || !smtp.port || !smtp.fromName || !smtp.fromEmail || (!smtpQuery.data?.hasPassword && Boolean(smtp.username) && !smtp.password) || saveSmtp.isPending} onClick={() => saveSmtp.mutate({ host: smtp.host, port: Number(smtp.port), username: smtp.username || null, password: smtp.password || null, fromName: smtp.fromName, fromEmail: smtp.fromEmail, secure: smtp.secure })} className="sm:col-span-2 bg-[#173c59] hover:bg-[#102f48]">Guardar SMTP</Button></div></DialogContent></Dialog></>;
}

function EventsView({ events, selectedId, onSelect }: { events: Event[]; selectedId: number; onSelect: (id: number) => void }) {
  const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: "", shortName: "", location: "", startDate: "", endDate: "" }); const create = trpc.events.create.useMutation({ onSuccess: () => { utils.workspace.events.invalidate(); toast.success("Nuevo congreso creado"); setOpen(false); } }); return <><PageTitle kicker="Reutilizar la plataforma" title="Congresos" description="Crea un nuevo congreso cuando lo necesites. Cada uno mantiene sus propias categorías, grupos y tareas." actions={<Button onClick={() => setOpen(true)} className="bg-[#173c59] hover:bg-[#102f48]"><Plus className="mr-2" size={16} />Nuevo congreso</Button>} /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{events.map(event => <button key={event.id} onClick={() => onSelect(event.id)} className={`rounded-2xl border p-5 text-left transition-all ${event.id === selectedId ? "border-[#b18843] bg-[#fffaf0] shadow-[0_6px_20px_rgba(158,115,40,.09)]" : "border-slate-200 bg-white hover:border-slate-300"}`}><div className="flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e8eef4] text-[#275170]"><CalendarDays size={20} /></span><Badge variant="outline" className="bg-white text-slate-600">{event.status}</Badge></div><h2 className="mt-5 font-serif text-xl text-[#172334]">{event.name}</h2><p className="mt-2 text-sm text-slate-500">{event.location || "Ubicación por definir"}</p><p className="mt-1 text-xs text-slate-400">{event.startDate || "Sin fecha"}{event.endDate && ` – ${event.endDate}`}</p></button>)}</div><Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Nuevo congreso</DialogTitle><DialogDescription>Se creará vacío y listo para añadir sus propias categorías, grupos y tareas.</DialogDescription></DialogHeader><div className="space-y-4"><div><Label>Nombre del congreso</Label><Input className="mt-1.5" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></div><div><Label>Nombre corto</Label><Input className="mt-1.5" value={form.shortName} onChange={e => setForm({ ...form, shortName: e.target.value })} placeholder="Ej.: OMC2028" /></div><div><Label>Ciudad</Label><Input className="mt-1.5" value={form.location} onChange={e => setForm({ ...form, location: e.target.value })} /></div><div className="grid grid-cols-2 gap-3"><div><Label>Inicio</Label><Input className="mt-1.5" placeholder="DD/MM/AAAA" value={form.startDate} onChange={e => setForm({ ...form, startDate: e.target.value })} /></div><div><Label>Fin</Label><Input className="mt-1.5" placeholder="DD/MM/AAAA" value={form.endDate} onChange={e => setForm({ ...form, endDate: e.target.value })} /></div></div><Button disabled={!form.name || !form.shortName} className="w-full bg-[#173c59] hover:bg-[#102f48]" onClick={() => create.mutate({ ...form, location: form.location || null, startDate: form.startDate || null, endDate: form.endDate || null })}>Crear congreso</Button></div></DialogContent></Dialog></>;
}

export default function Home() {
  const { user } = useAuth(); const [section, setSection] = useState<Section>("home"); const [selectedEvent, setSelectedEvent] = useState<number | null>(null); const [selectedTask, setSelectedTask] = useState<Task | null>(null); const [newTask, setNewTask] = useState(false);
  const access = trpc.workspace.access.useQuery(undefined, { enabled: Boolean(user) }); const eventQuery = trpc.workspace.events.useQuery(undefined, { enabled: Boolean(user) }); const events = (eventQuery.data ?? []) as Event[]; const eventId = selectedEvent ?? events[0]?.id ?? 0; const currentEvent = events.find(event => event.id === eventId); const isOrganizer = Boolean(access.data?.isOrganizer); const overview = trpc.workspace.overview.useQuery({ eventId }, { enabled: Boolean(user && eventId) }); const taskQuery = trpc.tasks.list.useQuery({ eventId }, { enabled: Boolean(user && eventId) }); const adminQuery = trpc.workspace.adminData.useQuery({ eventId }, { enabled: Boolean(user && eventId && isOrganizer) }); const data = (adminQuery.data ?? { categories: [], groups: [], members: [], groupMembers: [], taskAssignments: [], configuration: [] }) as AdminData; const tasks = (taskQuery.data ?? []) as Task[];
  const nav: NavigationItem[] = [{ id: "home", label: "Mis tareas", icon: ListTodo, allowedRoles: ALL_ROLES }, { id: "tasks", label: "Todas las tareas", icon: CheckCircle2, allowedRoles: ["admin"] }, { id: "reviews", label: "Verificaciones", icon: ClipboardCheck, allowedRoles: ["admin"] }, { id: "messages", label: "Mensajes", icon: Mail, allowedRoles: ["admin"] }, { id: "people", label: "Personas", icon: Users, allowedRoles: ["admin"] }, { id: "groups", label: "Grupos", icon: FolderPlus, allowedRoles: ["admin"] }, { id: "categories", label: "Categorías", icon: Layers3, allowedRoles: ["admin"] }, { id: "events", label: "Congresos", icon: CalendarDays, allowedRoles: ["admin"] }, { id: "settings", label: "Configuración", icon: Settings2, allowedRoles: ["admin"] }];
  const switchEvent = (id: number) => { setSelectedEvent(id); setSection("home"); };
  let page: React.ReactNode;
  if (!eventId && eventQuery.isLoading) page = <div className="h-64 grid place-items-center"><Loader2 className="animate-spin text-[#a7772f]" /></div>;
  else if (!eventId) page = <Empty title="Aún no hay congresos" body="Crea el primer congreso para empezar a organizar sus tareas." icon={CalendarDays} />;
  else if (section === "tasks") page = <TaskListView title="Todas las tareas" subtitle="Vista completa del congreso. Crea, cambia y asigna tareas rápidamente." tasks={tasks} categories={data.categories} data={data} isOrganizer onOpen={setSelectedTask} onCreate={() => setNewTask(true)} />;
  else if (section === "reviews") page = <ReviewsView eventId={eventId} />;
  else if (section === "messages") page = <MessagingView eventId={eventId} data={data} />;
  else if (section === "people") page = <PeopleView data={data} />;
  else if (section === "groups") page = <GroupsView data={data} eventId={eventId} />;
  else if (section === "categories") page = <CategoriesView categories={data.categories} eventId={eventId} />;
  else if (section === "events") page = <EventsView events={events} selectedId={eventId} onSelect={switchEvent} />;
  else if (section === "settings") page = <SettingsView data={data} onCategories={() => setSection("categories")} />;
  else page = <HomeView event={currentEvent} summary={overview.data} loading={overview.isLoading} onTasks={() => setSection(isOrganizer ? "tasks" : "home")} isOrganizer={isOrganizer} />;
  return <DashboardLayout active={section} onNavigate={id => setSection(id as Section)} items={nav} role={access.data?.role} roleLabel={access.data?.label}><div className="mb-6 flex flex-col gap-3 rounded-xl border border-slate-200 bg-white px-4 py-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#f4ead2] text-[#8d6423]"><CalendarDays size={16} /></span><div><p className="text-[10px] font-semibold uppercase tracking-[.08em] text-slate-400">Congreso activo</p><p className="text-sm font-semibold text-slate-700">{currentEvent?.name ?? "Cargando…"}</p></div></div>{events.length > 1 && <Select value={String(eventId)} onValueChange={id => switchEvent(Number(id))}><SelectTrigger className="w-full sm:w-[240px]"><SelectValue /></SelectTrigger><SelectContent>{events.map(event => <SelectItem key={event.id} value={String(event.id)}>{event.shortName}</SelectItem>)}</SelectContent></Select>}</div>{page}<TaskDialog task={selectedTask} eventId={eventId} categories={data.categories} members={data.members} groups={data.groups} assignments={data.taskAssignments} isOrganizer={isOrganizer} onClose={() => setSelectedTask(null)} /><NewTask open={newTask} eventId={eventId} categories={data.categories} onClose={() => setNewTask(false)} /></DashboardLayout>;
}
